sealed class FfiException: kotlin.Exception() {

    class InvalidInput(
        ) : FfiException() {
        override val message
            get() = ""
    }

    class IncompatibleModel(
        ) : FfiException() {
        override val message
            get() = ""
    }

    class Internal(
        ) : FfiException() {
        override val message
            get() = ""
    }

    class AccountMissing(
        ) : FfiException() {
        override val message
            get() = ""
    }

    class AccountLocked(
        ) : FfiException() {
        override val message
            get() = ""
    }

    class AccountBusy(
